insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'objective', 'Phân tích được sự chuyển hoá giữa động năng và thế năng của vật trong một số trường hợp đơn giản.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.content = 'Phân tích được sự chuyển hoá giữa động năng và thế năng của vật trong một số trường hợp đơn giản.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'objective', 'Vận dụng định luật bảo toàn cơ năng để giải bài tập đơn giản.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.content = 'Vận dụng định luật bảo toàn cơ năng để giải bài tập đơn giản.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'requirement', 'Nêu được cơ năng là tổng động năng và thế năng của vật.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.content = 'Nêu được cơ năng là tổng động năng và thế năng của vật.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'requirement', 'Vận dụng khái niệm cơ năng phân tích được sự chuyển hoá năng lượng trong một số trường hợp đơn giản.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.content = 'Vận dụng khái niệm cơ năng phân tích được sự chuyển hoá năng lượng trong một số trường hợp đơn giản.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'knowledge', 'text', '1. Cơ năng', 'Tổng động năng và thế năng của vật gọi là cơ năng của vật.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.section = 'knowledge' and x.title = '1. Cơ năng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'knowledge', 'formula', 'Công thức cơ năng', 'W = Wđ + Wt

Đơn vị của cơ năng là jun (J).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.section = 'knowledge' and x.title = 'Công thức cơ năng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'knowledge', 'text', '2. Sự chuyển hoá động năng – thế năng', 'Khi vật rơi từ trên cao xuống: độ cao giảm → thế năng giảm; tốc độ tăng → động năng tăng. Thế năng đã chuyển hoá thành động năng.
Khi vật được ném lên cao: động năng chuyển hoá dần thành thế năng.
Với con lắc dao động: ở vị trí cao nhất thế năng lớn nhất, động năng bằng 0; ở vị trí thấp nhất động năng lớn nhất, thế năng nhỏ nhất.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.section = 'knowledge' and x.title = '2. Sự chuyển hoá động năng – thế năng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'knowledge', 'text', '3. Bảo toàn cơ năng', 'Nếu cơ năng của vật không chuyển hoá thành dạng năng lượng khác thì tổng động năng và thế năng của vật luôn không đổi: cơ năng của vật được bảo toàn (ví dụ khi bỏ qua ma sát và lực cản của không khí).
Trong nhiều trường hợp, cơ năng có thể chuyển hoá thành các dạng năng lượng khác (như nhiệt năng do ma sát, lực cản của không khí); khi đó cơ năng không được bảo toàn nhưng năng lượng vẫn được bảo toàn.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.section = 'knowledge' and x.title = '3. Bảo toàn cơ năng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'knowledge', 'example', 'Ví dụ', 'Thả rơi một vật 2 kg từ độ cao 5 m (bỏ qua lực cản). Chọn mốc thế năng tại mặt đất.
• Cơ năng ban đầu: W = Wt = 10·2·5 = 100 J (Wđ = 0).
• Ngay trước khi chạm đất: Wt = 0 nên Wđ = W = 100 J → ½·2·v² = 100 → v = 10 m/s.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.section = 'knowledge' and x.title = 'Ví dụ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'experiment', 'text', 'Thí nghiệm SGK 3: Sự chuyển hoá động năng – thế năng của con lắc đơn (Hình 3.2)', 'Chuẩn bị: con lắc đơn (gồm vật nặng, sợi dây không dãn) được treo vào giá thí nghiệm.
Tiến hành:
• Kéo vật nặng đến vị trí A ở độ cao h rồi thả nhẹ; vật nặng chuyển động đến vị trí thấp nhất O, rồi tiếp tục đi lên và dừng lại ở điểm B, sau đó chuyển động ngược lại.
• So sánh độ cao của điểm B với độ cao của điểm A.
• Quan sát vật nặng chuyển động qua lại điểm O sau một khoảng thời gian.
Câu hỏi: nhận xét sự chuyển hoá giữa động năng và thế năng của vật nặng; vì sao sau một thời gian chuyển động, độ cao của vật nặng giảm dần?', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 3: Sự chuyển hoá động năng – thế năng của con lắc đơn (Hình 3.2)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3), 'experiment', 'text', 'Hoạt động SGK 3: Xe thế năng (Hình 3.4)', 'Quả nặng nối với trục xe qua ròng rọc cố định bởi một sợi dây mềm, không dãn; khi thả, quả nặng chuyển động từ trên xuống, sợi dây kéo trục xe làm bánh xe lăn.
• Mô tả sự chuyển hoá năng lượng từ khi thả quả nặng đến khi quả nặng chạm sàn xe.
• Cho độ cao ban đầu của quả nặng so với sàn xe là 8 cm, khối lượng quả nặng 20 g, khối lượng xe 50 g: tính tốc độ của xe ngay khi quả nặng chạm sàn xe, nếu coi toàn bộ thế năng của quả nặng chuyển hoá thành động năng của xe.
• Trong thực tế, tốc độ thu được nhỏ hơn giá trị tính toán – hãy giải thích.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 3) and x.section = 'experiment' and x.title = 'Hoạt động SGK 3: Xe thế năng (Hình 3.4)');

