update public.lessons set summary = 'Kim loại được tách khỏi quặng bằng điện phân nóng chảy, nhiệt luyện hoặc thuỷ luyện tuỳ mức độ hoạt động hoá học; hợp kim có nhiều ưu điểm hơn kim loại nguyên chất; gang và thép được sản xuất từ quặng sắt.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and summary is null;
