insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'objective', 'Trình bày được quá trình tách một số kim loại có nhiều ứng dụng: tách sắt ra khỏi iron(III) oxide bởi carbon oxide; tách nhôm ra khỏi aluminium oxide bởi phản ứng điện phân; tách kẽm khỏi zinc sulfide bởi oxygen và carbon (than).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.content = 'Trình bày được quá trình tách một số kim loại có nhiều ứng dụng: tách sắt ra khỏi iron(III) oxide bởi carbon oxide; tách nhôm ra khỏi aluminium oxide bởi phản ứng điện phân; tách kẽm khỏi zinc sulfide bởi oxygen và carbon (than).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'objective', 'Nêu được khái niệm hợp kim.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.content = 'Nêu được khái niệm hợp kim.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'objective', 'Giải thích vì sao trong một số trường hợp thực tiễn, kim loại được sử dụng dưới dạng hợp kim.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.content = 'Giải thích vì sao trong một số trường hợp thực tiễn, kim loại được sử dụng dưới dạng hợp kim.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'objective', 'Nêu được thành phần, tính chất đặc trưng của một số hợp kim phổ biến, quan trọng, hiện đại.', 5 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.content = 'Nêu được thành phần, tính chất đặc trưng của một số hợp kim phổ biến, quan trọng, hiện đại.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'objective', 'Trình bày được các giai đoạn cơ bản của quá trình sản xuất gang; quá trình sản xuất thép.', 6 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.content = 'Trình bày được các giai đoạn cơ bản của quá trình sản xuất gang; quá trình sản xuất thép.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'requirement', 'Giải thích được mối liên hệ giữa tính chất và ứng dụng của hợp kim.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.content = 'Giải thích được mối liên hệ giữa tính chất và ứng dụng của hợp kim.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'requirement', 'Trình bày được (thuyết trình/viết/vẽ) về các giai đoạn cơ bản của quá trình sản xuất gang và quá trình sản xuất thép.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.content = 'Trình bày được (thuyết trình/viết/vẽ) về các giai đoạn cơ bản của quá trình sản xuất gang và quá trình sản xuất thép.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'knowledge', 'text', '1. Phương pháp tách kim loại', 'Trong tự nhiên, kim loại chủ yếu tồn tại ở trong quặng dưới dạng hợp chất như oxide, muối. Ví dụ: aluminium oxide là thành phần chính trong quặng bauxite; iron(III) oxide là thành phần chủ yếu trong quặng hematite; zinc sulfide là thành phần chủ yếu trong quặng sphalerite. Một số kim loại quý như vàng, bạc,... có thể tồn tại dưới dạng đơn chất trong quặng.
Từ các quặng kim loại, người ta làm giàu quặng bằng cách loại bỏ tạp chất như đất, cát, đá,... Sau đó, tuỳ vào mức độ hoạt động hoá học của kim loại, có thể lựa chọn phương pháp hoá học phù hợp để tách kim loại ra khỏi hợp chất của nó:
• Phương pháp điện phân nóng chảy: tách các kim loại hoạt động hoá học mạnh như Na, Ca, Mg, Al,...
• Phương pháp nhiệt luyện: tách các kim loại hoạt động hoá học trung bình như Fe, Zn,...; dùng các chất như C, CO, H₂, Al,... tác dụng với oxide kim loại ở nhiệt độ cao, thu được kim loại.
• Phương pháp thuỷ luyện: tách các kim loại hoạt động hoá học yếu như Ag, Au,...: chuyển hợp chất của kim loại thành muối tan, sau đó dùng kim loại hoạt động hoá học mạnh hơn đẩy kim loại ra khỏi muối, tách chúng khỏi dung dịch.
Quy trình: Quặng →(làm giàu quặng) Hợp chất chứa kim loại →(phương pháp hoá học) Kim loại.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.section = 'knowledge' and x.title = '1. Phương pháp tách kim loại');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'knowledge', 'text', '2. Tách một số kim loại có nhiều ứng dụng', 'a) Tách nhôm ra khỏi aluminium oxide bằng phản ứng điện phân (Hình 20.1). Nguyên liệu: quặng bauxite (thành phần chính là Al₂O₃). Trong công nghiệp, nhôm được sản xuất bằng phương pháp điện phân aluminium oxide nóng chảy:
2Al₂O₃ →(điện phân nóng chảy, cryolite) 4Al + 3O₂
Cryolite dùng để hạ nhiệt độ nóng chảy của Al₂O₃, nhằm tiết kiệm năng lượng. Cực dương bằng than chì, cực âm bằng than chì; nhôm nóng chảy được tháo ra ở đáy bể.
b) Tách sắt ra khỏi iron(III) oxide: ở nhiệt độ cao, sắt được tách ra khỏi iron(III) oxide bởi carbon monoxide: Fe₂O₃ + 3CO →(t°) 2Fe + 3CO₂.
c) Tách kẽm ra khỏi zinc sulfide: quặng chứa zinc sulfide (ZnS) được đốt trong không khí để chuyển thành zinc oxide (ZnO): 2ZnS + 3O₂ →(t°) 2ZnO + 2SO₂. Tiếp theo, kẽm được tách ra khỏi zinc oxide bởi carbon: ZnO + C →(t°) Zn + CO.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.section = 'knowledge' and x.title = '2. Tách một số kim loại có nhiều ứng dụng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'knowledge', 'text', '3. Hợp kim', 'Khái niệm: hợp kim là vật liệu kim loại có chứa ít nhất một kim loại cơ bản và một số kim loại hoặc phi kim khác. Kim loại cơ bản là kim loại chiếm thành phần chính trong hợp kim. Ví dụ: thép có kim loại cơ bản là sắt; đuy-ra (duralumin) có kim loại cơ bản là nhôm,...
Ưu điểm: hợp kim thường có nhiều ưu điểm vượt trội so với kim loại nguyên chất về độ cứng, độ bền, khả năng chống ăn mòn và gỉ sét, phù hợp với nhiều ứng dụng. Do đó, chúng được sử dụng phổ biến trong đời sống và trong công nghiệp.
Một số hợp kim phổ biến:
• Gang và thép là hai hợp kim quan trọng của sắt với carbon và một số nguyên tố khác (carbon chiếm hàm lượng từ 2% đến 5% trong gang và dưới 2% trong thép). Thép có nhiều ưu điểm hơn gang về độ cứng, độ đàn hồi, khả năng chịu lực nên được sử dụng rộng rãi trong các công trình xây dựng, giao thông. Gang cũng giòn hơn thép, thường dùng để đúc các chi tiết máy, ống dẫn nước, nắp cống,...
• Inox là một loại thép đặc biệt, ngoài sắt và carbon còn có các nguyên tố khác như chromium, nickel. Inox cũng khó bị gỉ, được sử dụng làm đồ gia dụng, thiết bị y tế,...
• Đuy-ra (duralumin) là hợp kim của nhôm với đồng, manganese, magnesium,... Đuy-ra nhẹ tương đương nhôm nhưng bền và cứng hơn nhiều, được dùng làm vật liệu chế tạo máy bay, ô tô,...
Em có biết: dây chì của hệ thống dập lửa tự động được làm từ hợp kim có nhiệt độ nóng chảy thấp (hợp kim Wood).', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.section = 'knowledge' and x.title = '3. Hợp kim');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'knowledge', 'text', '4. Sản xuất gang, thép', 'Sắt tinh khiết hầu như không được sử dụng trong cuộc sống, nhưng các hợp kim của sắt là gang và thép lại được sử dụng phổ biến trong công nghiệp và đời sống.
Sản xuất gang từ nguồn quặng chứa iron(III) oxide (Hình 20.2): nguyên liệu gồm quặng sắt (thường là quặng hematite với thành phần chính là Fe₂O₃), than cốc và chất tạo xỉ như CaCO₃, SiO₂,... Quặng sắt, than cốc, đá vôi được đưa vào lò qua miệng lò, chuyển dần từ trên xuống. Không khí nóng được thổi vào từ dưới lên. Các giai đoạn chính:
– Phản ứng tạo thành khí CO: C + O₂ →(t°) CO₂;  C + CO₂ →(t°) 2CO.
– Khí CO phản ứng với các oxide của sắt trong quặng: 3CO + Fe₂O₃ →(t°) 2Fe + 3CO₂. Sắt nóng chảy hoà tan một lượng nhỏ carbon cùng một số nguyên tố khác tạo thành gang lỏng.
– Đá vôi bị phân huỷ thành CaO; CaO kết hợp với các oxide như SiO₂ trong quặng tạo thành xỉ: CaO + SiO₂ →(t°) CaSiO₃. Xỉ nhẹ nổi lên trên gang lỏng, được đưa ra ngoài qua cửa tháo xỉ.
Sản xuất thép (Hình 20.3): nguyên liệu chính là gang (hoặc thép phế liệu) và khí oxygen. Khí oxygen được thổi vào lò đựng gang nóng chảy ở nhiệt độ cao, đốt cháy các tạp chất trong gang (carbon, sulfur, silicon, manganese,...). Các oxide tạo thành ở dạng khí (CO₂, SO₂,...) thoát ra theo khí thải, còn các oxide dạng rắn (SiO₂, MnO₂,...) tạo xỉ nhẹ nổi lên trên thép lỏng và được tách ra để thu lấy thép.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.section = 'knowledge' and x.title = '4. Sản xuất gang, thép');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'knowledge', 'example', 'Câu hỏi SGK', '• Điểm giống nhau của quá trình tách kẽm và tách sắt: đều là phương pháp nhiệt luyện, dùng carbon (hoặc CO) để tách kim loại khỏi oxide ở nhiệt độ cao. Điểm khác: với kẽm, quặng zinc sulfide phải đốt trong không khí để chuyển thành zinc oxide trước.
• Natri là kim loại hoạt động hoá học mạnh nên không thể tách bằng nhiệt luyện, phải dùng điện phân nóng chảy.
• Phương pháp thường dùng tách K, Na, Al,...: điện phân nóng chảy; tách Zn, Fe: nhiệt luyện.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.section = 'knowledge' and x.title = 'Câu hỏi SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20), 'experiment', 'text', 'Hoạt động SGK 20: Sơ đồ bể điện phân và lò luyện gang (bài này không có thí nghiệm thực hành)', 'SGK Bài 20 trình bày các quá trình sản xuất bằng sơ đồ, không có thí nghiệm thực hành.
• Hình 20.1 – Sơ đồ bể điện phân aluminium oxide nóng chảy: cực dương và cực âm bằng than chì; hỗn hợp Al₂O₃ và cryolite nóng chảy; nhôm nóng chảy ở đáy bể.
• Hình 20.2 – Sơ đồ lò luyện gang: nguyên liệu (quặng sắt, than cốc, đá vôi) đi từ trên xuống, không khí nóng thổi từ dưới lên; gang lỏng và xỉ được tháo ra ở cửa tháo.
• Hình 20.3 – Sơ đồ lò thổi luyện thép: thổi khí oxygen vào gang lỏng.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 20) and x.section = 'experiment' and x.title = 'Hoạt động SGK 20: Sơ đồ bể điện phân và lò luyện gang (bài này không có thí nghiệm thực hành)');

-- Bài 21
update public.lessons set summary = 'Phi kim như carbon, lưu huỳnh, chlorine có nhiều ứng dụng; phi kim khác kim loại về tính dẫn điện, nhiệt độ nóng chảy, nhiệt độ sôi, khối lượng riêng và xu hướng nhận electron.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'objective', 'Nêu được ứng dụng của một số đơn chất phi kim thiết thực trong cuộc sống (than, lưu huỳnh, khí chlorine,...).', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.content = 'Nêu được ứng dụng của một số đơn chất phi kim thiết thực trong cuộc sống (than, lưu huỳnh, khí chlorine,...).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'objective', 'Chỉ ra được sự khác nhau cơ bản về một số tính chất giữa phi kim và kim loại: khả năng dẫn điện, nhiệt độ nóng chảy, nhiệt độ sôi, khối lượng riêng; khả năng tạo ion dương, ion âm; phản ứng với oxygen tạo oxide acid, oxide base.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.content = 'Chỉ ra được sự khác nhau cơ bản về một số tính chất giữa phi kim và kim loại: khả năng dẫn điện, nhiệt độ nóng chảy, nhiệt độ sôi, khối lượng riêng; khả năng tạo ion dương, ion âm; phản ứng với oxygen tạo oxide acid, oxide base.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'requirement', 'Biết được ưu điểm của khẩu trang than hoạt tính so với khẩu trang thường.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.content = 'Biết được ưu điểm của khẩu trang than hoạt tính so với khẩu trang thường.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'requirement', 'Biết được vai trò của than hoạt tính trong các máy lọc nước.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.content = 'Biết được vai trò của than hoạt tính trong các máy lọc nước.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'knowledge', 'text', '1. Ứng dụng của một số phi kim quan trọng', 'Carbon: trong tự nhiên, đơn chất carbon tồn tại ở các dạng chính như: kim cương, than chì (graphite), carbon vô định hình (than gỗ, than xương, mồ hóng,...). Các loại than như than gỗ, than xương,... có khả năng giữ trên bề mặt của nó các phân tử chất khí, chất tan trong dung dịch. Tính chất này được gọi là tính hấp phụ. Dựa vào tính hấp phụ, carbon ở dạng than hoạt tính được dùng trong mặt nạ phòng độc, chất khử màu, khử mùi. Ngoài ra: than cốc dùng làm nhiên liệu, nguyên liệu trong công nghiệp luyện kim; than chì làm điện cực, chất bôi trơn, ruột bút chì; kim cương làm đồ trang sức, mũi khoan, dao cắt kính;...
Lưu huỳnh là nguyên liệu quan trọng cho nhiều ngành công nghiệp: lưu hoá cao su, sản xuất dược phẩm, sản xuất sulfuric acid, sản xuất thuốc diệt nấm, sản xuất pháo hoa, diêm (Hình 21.2). Lưu hoá cao su: quá trình lưu hoá cao su được phát minh bởi Charles Goodyear vào năm 1839; bản chất là tạo các cầu nối lưu huỳnh giữa các mạch cao su để hình thành mạng lưới chắc chắn, đàn hồi hơn.
Chlorine có nhiều ứng dụng trong cuộc sống và trong các ngành công nghiệp như khử trùng nước sinh hoạt; sản xuất nước Javel, chất tẩy rửa,...; tẩy trắng vải, sợi, bột giấy,...; sản xuất chất dẻo,...', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.section = 'knowledge' and x.title = '1. Ứng dụng của một số phi kim quan trọng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'knowledge', 'text', '2. Sự khác nhau về tính chất vật lí giữa phi kim và kim loại', 'a) Tính dẫn điện: trong khi các kim loại dẫn điện tốt thì phi kim thường không dẫn điện. Silicon tinh khiết là chất bán dẫn. Than chì có tính dẫn điện nhưng yếu hơn kim loại.
b) Nhiệt độ nóng chảy, nhiệt độ sôi: phần lớn phi kim có nhiệt độ nóng chảy, nhiệt độ sôi thấp hơn kim loại. Ở nhiệt độ thường, trong khi hầu hết các kim loại ở thể rắn (riêng thuỷ ngân ở thể lỏng) thì phi kim có thể tồn tại ở thể khí (hydrogen, nitrogen, oxygen, fluorine, chlorine,...), thể lỏng (bromine) hay thể rắn (carbon, silicon, phosphorus, lưu huỳnh,...).
c) Khối lượng riêng: phần lớn phi kim có khối lượng riêng nhỏ hơn kim loại.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.section = 'knowledge' and x.title = '2. Sự khác nhau về tính chất vật lí giữa phi kim và kim loại');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'knowledge', 'text', '3. Sự khác nhau về tính chất hoá học giữa phi kim và kim loại', 'a) Phản ứng của kim loại với phi kim: trong phản ứng hoá học, các kim loại dễ nhường electron để tạo ra ion dương, còn các phi kim dễ nhận electron tạo ion âm.
Ví dụ: Na → Na⁺ + 1e;  Cl + 1e → Cl⁻;  2Na + Cl₂ → 2NaCl.
b) Phản ứng của phi kim và kim loại với oxygen: kim loại tác dụng với oxygen thường tạo thành oxide base, trong khi phi kim tác dụng với oxygen thường tạo thành oxide acid.
Ví dụ: 2Mg + O₂ →(t°) 2MgO;  S + O₂ →(t°) SO₂.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.section = 'knowledge' and x.title = '3. Sự khác nhau về tính chất hoá học giữa phi kim và kim loại');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'knowledge', 'text', 'Em đã học', 'Phi kim có nhiều ứng dụng quan trọng: than hoạt tính được dùng làm mặt nạ phòng độc, khử màu, khử mùi; than cốc là nhiên liệu, chất phản ứng trong nhiều ngành công nghiệp; lưu huỳnh là nguyên liệu sản xuất sulfuric acid; chlorine dùng để khử trùng, tẩy màu, sản xuất nhựa, hydrochloric acid,... Khác với kim loại, hầu hết các nguyên tố phi kim không dẫn điện; phần lớn phi kim có nhiệt độ nóng chảy, nhiệt độ sôi và khối lượng riêng nhỏ hơn so với kim loại. Trong các phản ứng giữa kim loại và phi kim, kim loại là chất nhường electron, phi kim là chất nhận electron. Nhiều kim loại tác dụng với oxygen tạo thành oxide base. Phi kim tác dụng với oxygen thường tạo thành oxide acid.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.section = 'knowledge' and x.title = 'Em đã học');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21), 'experiment', 'text', 'Hoạt động tìm hiểu: tính hấp phụ của than gỗ (Hình 21.1)', 'Bố trí: phễu lọc có bông, bột than gỗ (kẹp ở giá); rót từ từ nước màu pha loãng vào phễu. Dung dịch thu được trong cốc thuỷ tinh bị mất màu do than gỗ đã giữ lại các phân tử chất màu trên bề mặt (tính hấp phụ).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 21) and x.section = 'experiment' and x.title = 'Hoạt động tìm hiểu: tính hấp phụ của than gỗ (Hình 21.1)');

-- Bài 22
update public.lessons set summary = 'Hợp chất hữu cơ là hợp chất của carbon (trừ CO, CO₂, muối carbonate,...); mỗi chất có công thức phân tử và công thức cấu tạo; carbon luôn có hoá trị IV.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'objective', 'Nêu được khái niệm hợp chất hữu cơ, hoá học hữu cơ.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.content = 'Nêu được khái niệm hợp chất hữu cơ, hoá học hữu cơ.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'objective', 'Nêu được khái niệm công thức phân tử, công thức cấu tạo và ý nghĩa của nó; đặc điểm cấu tạo hợp chất hữu cơ.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.content = 'Nêu được khái niệm công thức phân tử, công thức cấu tạo và ý nghĩa của nó; đặc điểm cấu tạo hợp chất hữu cơ.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'objective', 'Phân biệt được hợp chất hữu cơ hay vô cơ theo công thức phân tử.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.content = 'Phân biệt được hợp chất hữu cơ hay vô cơ theo công thức phân tử.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'objective', 'Trình bày được sự phân loại sơ bộ hợp chất hữu cơ gồm hydrocarbon và dẫn xuất của hydrocarbon.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.content = 'Trình bày được sự phân loại sơ bộ hợp chất hữu cơ gồm hydrocarbon và dẫn xuất của hydrocarbon.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'requirement', 'Phân biệt được hợp chất hữu cơ và vô cơ.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.content = 'Phân biệt được hợp chất hữu cơ và vô cơ.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'knowledge', 'text', '1. Khái niệm hợp chất hữu cơ và hoá học hữu cơ', 'Hợp chất của carbon là hợp chất hữu cơ, trừ carbon monoxide, carbon dioxide, các muối carbonate,...
Ngành khoa học chuyên nghiên cứu về các hợp chất hữu cơ là một chuyên ngành của ngành Hoá học, được đặt tên là chuyên ngành Hoá học hữu cơ.
Một số hợp chất hữu cơ phổ biến (Hình 22.1): butane C₄H₁₀ (một loại khí hoá lỏng, dùng làm nhiên liệu); ethylic alcohol C₂H₅OH (có trong thành phần của đồ uống có cồn); acetic acid CH₃COOH (có trong thành phần của các loại giấm); urea CO(NH₂)₂ (một loại phân đạm).
Em có biết: thuật ngữ “hoá học hữu cơ” được nhà hoá học người Thuỵ Điển Jacob Berzelius đưa ra lần đầu tiên vào năm 1806, khi ông nghiên cứu các hợp chất có nguồn gốc sinh vật. Tại thời điểm đó, các nhà khoa học vẫn cho rằng các hợp chất hữu cơ chỉ được hình thành trong cơ thể sinh vật nhờ “lực sống”. Đến năm 1828, khi nhà hoá học người Đức Friedrich Wöhler tổng hợp được hợp chất hữu cơ urea từ chất vô cơ thì thuật ngữ “hoá học hữu cơ” bắt đầu được hiểu như cách hiểu hiện nay.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.section = 'knowledge' and x.title = '1. Khái niệm hợp chất hữu cơ và hoá học hữu cơ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'knowledge', 'text', '2. Công thức phân tử và công thức cấu tạo', 'Để hiểu rõ mối liên hệ giữa cấu tạo và tính chất của mỗi chất hữu cơ, không chỉ cần quan tâm đến công thức phân tử của chất mà còn cần quan tâm cả đến công thức cấu tạo của chất đó.
• Công thức phân tử là công thức cho biết thành phần nguyên tố và số lượng nguyên tử của mỗi nguyên tố trong phân tử.
• Công thức cấu tạo là công thức cho biết trật tự liên kết và cách thức liên kết giữa các nguyên tử trong phân tử.
Trong công thức cấu tạo, liên kết cộng hoá trị giữa hai nguyên tử bằng một cặp electron dùng chung được gọi là liên kết đơn, biểu diễn bằng một gạch nối (–); còn liên kết cộng hoá trị giữa hai nguyên tử bằng hai cặp electron dùng chung gọi là liên kết đôi, biểu diễn bằng hai gạch nối (=).
Công thức cấu tạo còn được viết dưới dạng thu gọn bằng cách viết gộp nguyên tử hydrogen vào nguyên tử liên kết với nó thành từng nhóm.
Ví dụ: C₂H₆ có công thức cấu tạo thu gọn CH₃–CH₃; C₂H₄ có công thức cấu tạo thu gọn CH₂=CH₂.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.section = 'knowledge' and x.title = '2. Công thức phân tử và công thức cấu tạo');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'knowledge', 'text', '3. Đặc điểm cấu tạo hợp chất hữu cơ', 'Thành phần phân tử hợp chất hữu cơ nhất thiết phải chứa nguyên tố carbon, thường có các nguyên tố như hydrogen, oxygen, nitrogen, chlorine, sulfur,... Có thể nhận thấy rằng các hợp chất hữu cơ được tạo thành chủ yếu từ các nguyên tố phi kim, vì vậy liên kết hoá học chủ yếu trong các hợp chất này là liên kết cộng hoá trị.
Trong phân tử hợp chất hữu cơ, carbon luôn có hoá trị IV; các nguyên tử carbon không chỉ có khả năng liên kết với nguyên tử của nguyên tố khác mà còn có thể liên kết với nhau tạo thành mạch carbon (Hình 22.3): mạch hở không phân nhánh, mạch hở phân nhánh, mạch vòng. Điều này dẫn đến hệ quả là có rất nhiều chất hữu cơ khác nhau nhưng lại có cùng công thức phân tử.
Tính chất của hợp chất hữu cơ phụ thuộc đồng thời vào thành phần phân tử và cấu tạo hoá học của chúng. Ví dụ (Bảng 22.1): methyl chloride CH₃Cl – chất khí, tan rất ít trong nước, không tác dụng với natri; ethylic alcohol C₂H₆O (CH₃–CH₂–OH) – chất lỏng, tan vô hạn trong nước, tác dụng với natri; dimethyl ether C₂H₆O (CH₃–O–CH₃) – chất khí, tan ít trong nước, không tác dụng với natri. Ethylic alcohol và dimethyl ether cùng công thức phân tử C₂H₆O nhưng cấu tạo khác nhau nên tính chất khác nhau.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.section = 'knowledge' and x.title = '3. Đặc điểm cấu tạo hợp chất hữu cơ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'knowledge', 'text', '4. Phân loại hợp chất hữu cơ', 'Có nhiều cơ sở khác nhau để phân loại hợp chất hữu cơ, trong đó phổ biến nhất là phân loại dựa trên thành phần nguyên tố. Trên cơ sở này hợp chất hữu cơ được chia làm hai loại:
• Hydrocarbon là loại hợp chất hữu cơ mà trong thành phần phân tử chỉ chứa các nguyên tố carbon và hydrogen.
• Dẫn xuất của hydrocarbon là loại hợp chất hữu cơ mà trong thành phần phân tử, ngoài nguyên tố carbon còn có nguyên tố khác như oxygen, nitrogen, chlorine,... và thường có hydrogen.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.section = 'knowledge' and x.title = '4. Phân loại hợp chất hữu cơ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'knowledge', 'example', 'Bài tập SGK', '• Sắp xếp các hợp chất C₆H₆, H₂SO₄, C₆H₁₂O₆, H₂CO₃, CaCO₃, KNO₃, C₂H₄, NaOH, Al₂O₃, CH₃Cl, CH₃OH thành hai nhóm. Nhóm hợp chất hữu cơ: C₆H₆, C₆H₁₂O₆, C₂H₄, CH₃Cl, CH₃OH. Nhóm hợp chất vô cơ: H₂SO₄, H₂CO₃, CaCO₃, KNO₃, NaOH, Al₂O₃ (H₂CO₃ và CaCO₃ thuộc loại ngoại lệ: carbonic acid, muối carbonate).
• Hydrocarbon: CH₄, CH₂=CH₂, CH₃CH₂CH₃, CH₃CH=CH₂; dẫn xuất của hydrocarbon: CH₃Cl, CH₃CH₂OH, CH₃COOH, CH₃NH₂, CH₃COOCH₂CH₃.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.section = 'knowledge' and x.title = 'Bài tập SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22), 'experiment', 'text', 'Hoạt động SGK 22: Công thức phân tử, công thức cấu tạo (bài này không có thí nghiệm thực hành)', 'SGK Bài 22 gồm các hoạt động quan sát công thức và mô hình, không có thí nghiệm thực hành.
• Hình 22.1: butane C₄H₁₀, ethylic alcohol C₂H₅OH, acetic acid CH₃COOH, urea CO(NH₂)₂ – đặc điểm chung của thành phần nguyên tử là đều chứa carbon.
• Hình 22.2: phân biệt công thức phân tử và công thức cấu tạo; viết công thức cấu tạo đầy đủ dưới dạng thu gọn; so sánh công thức phân tử của các chất có cấu tạo khác nhau (C₄H₁₀ có hai cấu tạo; C₂H₆O có hai cấu tạo).
• Hình 22.3: mạch carbon hở không phân nhánh, hở phân nhánh và mạch vòng.
• Dùng bộ mô hình lắp ghép phân tử để lắp các công thức cấu tạo có thể có của C₄H₁₀ và C₅H₁₂.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 22) and x.section = 'experiment' and x.title = 'Hoạt động SGK 22: Công thức phân tử, công thức cấu tạo (bài này không có thí nghiệm thực hành)');

-- Bài 23
update public.lessons set summary = 'Alkane là hydrocarbon mạch hở chỉ có liên kết đơn, công thức chung CₙH₂ₙ₊₂; alkane cháy toả nhiều nhiệt nên được dùng làm nhiên liệu.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Nêu được khái niệm hydrocarbon, alkane.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Nêu được khái niệm hydrocarbon, alkane.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Viết được công thức cấu tạo và gọi tên được một số alkane đơn giản và thông dụng (C1 – C4).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Viết được công thức cấu tạo và gọi tên được một số alkane đơn giản và thông dụng (C1 – C4).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Viết được phương trình hoá học phản ứng đốt cháy của butane.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Viết được phương trình hoá học phản ứng đốt cháy của butane.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Tiến hành được (hoặc quan sát qua liệu điện tử) thí nghiệm đốt cháy butane từ đó rút ra được tính chất hoá học cơ bản của alkane.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Tiến hành được (hoặc quan sát qua liệu điện tử) thí nghiệm đốt cháy butane từ đó rút ra được tính chất hoá học cơ bản của alkane.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'objective', 'Trình bày được ứng dụng làm nhiên liệu của alkane trong thực tiễn.', 5 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Trình bày được ứng dụng làm nhiên liệu của alkane trong thực tiễn.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'requirement', 'Nêu được ứng dụng làm nhiên liệu của các alkane.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Nêu được ứng dụng làm nhiên liệu của các alkane.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'requirement', 'Sử dụng nhiên liệu như gas, xăng, dầu hoả tiết kiệm, hiệu quả.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.content = 'Sử dụng nhiên liệu như gas, xăng, dầu hoả tiết kiệm, hiệu quả.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'text', '1. Khái niệm hydrocarbon, alkane', 'Một số hydrocarbon thông dụng (Hình 23.1): methane (có trong khí bùn ao), propane (có trong bình gas), ethylene (có trong khí sinh ra từ một số loại quả chín).
Hydrocarbon là loại hợp chất hữu cơ mà thành phần phân tử chỉ chứa các nguyên tố carbon và hydrogen. Hydrocarbon gồm nhiều loại khác nhau, như alkane, alkene,...
Alkane là những hydrocarbon mạch hở, phân tử chỉ chứa các liên kết đơn.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = '1. Khái niệm hydrocarbon, alkane');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'text', '2. Cấu tạo phân tử và danh pháp của alkane (Bảng 23.1)', '• CH₄ – methane
• C₂H₆: CH₃–CH₃ – ethane
• C₃H₈: CH₃–CH₂–CH₃ – propane
• C₄H₁₀: CH₃–CH₂–CH₂–CH₃ – butane
Trong công thức phân tử của alkane, khi tăng thêm một nguyên tử carbon thì số nguyên tử hydrogen tăng thêm 2. Thành phần phân tử của các alkane hơn kém nhau một hay nhiều nhóm CH₂.
Alkane có công thức chung là CₙH₂ₙ₊₂ (n ≥ 1, n là số nguyên, dương).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = '2. Cấu tạo phân tử và danh pháp của alkane (Bảng 23.1)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'text', '3. Phản ứng cháy của alkane', 'Khi đốt cháy alkane trong không khí thu được sản phẩm chủ yếu là khí carbon dioxide và hơi nước:
C₃H₈ + 5O₂ →(t°) 3CO₂ + 4H₂O
C₄H₁₀ + 13/2 O₂ →(t°) 4CO₂ + 5H₂O
Phản ứng cháy của alkane toả nhiệt mạnh, vì vậy alkane được sử dụng làm nhiên liệu trong cuộc sống và trong sản xuất. Bên cạnh các sản phẩm trên, một phần alkane cháy không hoàn toàn tạo một lượng nhỏ sản phẩm là muội than (một dạng đơn chất của carbon) và carbon monoxide.
Các alkane khá bền ở điều kiện thường, chúng không phản ứng với acid, base và nhiều chất khác.
Mở rộng: công thức tổng quát CₙH₂ₙ₊₂ + (3n + 1)/2 O₂ →(t°) nCO₂ + (n + 1)H₂O.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = '3. Phản ứng cháy của alkane');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'text', '4. Ứng dụng làm nhiên liệu của alkane (Bảng 23.2)', '• Nhiên liệu khí hoá lỏng: propane và butane dễ hoá lỏng, được dùng làm nhiên liệu cho bật lửa, bếp gas,...
• Nhiên liệu lỏng: các alkane ở trạng thái lỏng có thể dùng làm nhiên liệu dưới dạng xăng, dầu hoả, dầu diesel và nhiên liệu phản lực (jet fuel).
• Nhiên liệu rắn: các alkane ở trạng thái rắn có thể dùng làm nhiên liệu dưới dạng nến paraffin.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = '4. Ứng dụng làm nhiên liệu của alkane (Bảng 23.2)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'knowledge', 'example', 'Bài tập SGK', '• Phương trình cháy: CH₄ + 2O₂ →(t°) CO₂ + 2H₂O;  2C₂H₆ + 7O₂ →(t°) 4CO₂ + 6H₂O.
• Nhiệt lượng toả ra khi đốt cháy hoàn toàn 1 gam alkane (Bảng): methane 891/16 ≈ 55,7 kJ; ethane 1 561/30 ≈ 52,0 kJ; propane 2 220/44 ≈ 50,5 kJ; butane 2 878/58 ≈ 49,6 kJ. Đốt cháy 1 gam methane toả ra nhiều nhiệt nhất.
• Khí gas là hỗn hợp propane và butane có tỉ lệ thể tích 1 : 1 (tức tỉ lệ mol 1 : 1): 1 mol propane (44 g) và 1 mol butane (58 g) toả 2 220 + 2 878 = 5 098 kJ; đốt 1 kg khí gas toả ra khoảng 5 098/0,102 ≈ 5,0·10⁴ kJ.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'knowledge' and x.title = 'Bài tập SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23), 'experiment', 'text', 'Thí nghiệm: Tìm hiểu về phản ứng đốt cháy của butane (Hình 23.2)', 'Chuẩn bị: bật lửa gas (chứa butane) loại dài; bình tam giác bằng thuỷ tinh chịu nhiệt, sạch và khô, có nút; ống nghiệm đựng dung dịch nước vôi trong.
Tiến hành: đưa đầu bật lửa vào miệng bình tam giác úp ngược, đánh lửa bật gas và giữ lửa cháy cho tới khi thấy thành bình tam giác mờ đi thì dừng lại. Quay xuống bình tam giác lại và đổ nước vôi trong vào. Sau đó, đậy bình bằng nút và lắc đều.
Kết quả: thành bình mờ đi do có hơi nước tạo thành; nước vôi trong vẩn đục do có carbon dioxide tạo thành. Sản phẩm của phản ứng đốt cháy butane là carbon dioxide và hơi nước.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 23) and x.section = 'experiment' and x.title = 'Thí nghiệm: Tìm hiểu về phản ứng đốt cháy của butane (Hình 23.2)');

-- Bài 24
update public.lessons set summary = 'Alkene là hydrocarbon mạch hở có một liên kết đôi C=C, công thức chung CₙH₂ₙ; ethylene cháy, cộng với bromine và trùng hợp thành polyethylene.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Nêu được khái niệm alkene.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Nêu được khái niệm alkene.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Viết được công thức cấu tạo và nêu được tính chất vật lí của ethylene.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Viết được công thức cấu tạo và nêu được tính chất vật lí của ethylene.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Trình bày được tính chất hoá học của ethylene (phản ứng cháy, phản ứng làm mất màu nước bromine, phản ứng trùng hợp). Viết được các phương trình hoá học xảy ra.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Trình bày được tính chất hoá học của ethylene (phản ứng cháy, phản ứng làm mất màu nước bromine, phản ứng trùng hợp). Viết được các phương trình hoá học xảy ra.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Tiến hành được thí nghiệm (hoặc quan sát thí nghiệm) của ethylene: phản ứng đốt cháy, phản ứng làm mất màu nước bromine, quan sát và giải thích được tính chất hoá học cơ bản của alkene.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Tiến hành được thí nghiệm (hoặc quan sát thí nghiệm) của ethylene: phản ứng đốt cháy, phản ứng làm mất màu nước bromine, quan sát và giải thích được tính chất hoá học cơ bản của alkene.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'objective', 'Trình bày được một số ứng dụng của ethylene: tổng hợp ethylic alcohol, tổng hợp nhựa polyethylene (PE).', 5 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Trình bày được một số ứng dụng của ethylene: tổng hợp ethylic alcohol, tổng hợp nhựa polyethylene (PE).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'requirement', 'Nhận biết và lựa chọn được các sản phẩm làm từ nguyên liệu polyethylene và sử dụng chúng đúng cách để bảo vệ môi trường.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.content = 'Nhận biết và lựa chọn được các sản phẩm làm từ nguyên liệu polyethylene và sử dụng chúng đúng cách để bảo vệ môi trường.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'text', '1. Khái niệm alkene', 'Cho công thức cấu tạo của một số alkene: CH₂=CH₂; CH₃–CH=CH₂; CH₃–CH=CH–CH₃. Điểm chung: phân tử có một liên kết đôi C=C.
Alkene là những hydrocarbon mạch hở, trong phân tử có một liên kết đôi C=C. Công thức chung của các alkene có dạng CₙH₂ₙ (với n ≥ 2, n là các số nguyên, dương).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = '1. Khái niệm alkene');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'text', '2. Ethylene: tính chất vật lí và cấu tạo phân tử', 'Tính chất vật lí: ethylene là chất khí ở điều kiện thường (hoá lỏng ở −104 °C và hoá rắn ở −169 °C), không màu, hầu như không tan trong nước, tan ít trong các dung môi hữu cơ như ethylic alcohol.
Cấu tạo phân tử: công thức phân tử của ethylene là C₂H₄; công thức cấu tạo là CH₂=CH₂. Phân tử ethylene có liên kết đôi C=C, trong đó có một liên kết kém bền, dễ bị phá vỡ trong các phản ứng hoá học.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = '2. Ethylene: tính chất vật lí và cấu tạo phân tử');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'text', '3. Tính chất hoá học của ethylene', 'a) Phản ứng cháy: tương tự alkane, phản ứng đốt cháy alkene tạo ra sản phẩm chủ yếu là khí carbon dioxide và hơi nước. Phản ứng toả ra nhiều nhiệt:
C₂H₄ + 3O₂ →(t°) 2CO₂ + 2H₂O
b) Phản ứng cộng: khi ethylene phản ứng với nước bromine, phân tử bromine đã cộng hợp vào nối đôi C=C trong phân tử ethylene, liên kết kém bền trong liên kết đôi bị phá vỡ, tạo thành sản phẩm 1,2-dibromoethane:
CH₂=CH₂ + Br–Br → CH₂Br–CH₂Br   (viết gọn: C₂H₄ + Br₂ → C₂H₄Br₂)
Phản ứng trên gọi là phản ứng cộng.
c) Phản ứng trùng hợp: ở điều kiện thích hợp, các phân tử ethylene cộng hợp liên tiếp với nhau, liên kết kém bền trong liên kết đôi bị phá vỡ, tạo thành chất có khối lượng phân tử lớn:
nCH₂=CH₂ →(t°, p, xúc tác) (–CH₂–CH₂–)ₙ    (ethylene → polyethylene)
Phản ứng trên gọi là phản ứng trùng hợp. Polyethylene (nhựa PE) là chất rắn, không tan trong nước, không độc, được dùng để sản xuất túi đựng, màng bọc, chai, bình chứa,... Tuy nhiên, nhựa PE rất khó phân huỷ sinh học, có thể tồn tại bền trong môi trường hàng trăm năm, vì vậy cần giảm thiểu việc thải các sản phẩm làm từ nhựa PE ra ngoài môi trường.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = '3. Tính chất hoá học của ethylene');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'text', '4. Ứng dụng của ethylene (Hình 24.2)', 'Ethylene là nguyên liệu quan trọng cho ngành công nghiệp sản xuất hoá chất và tổng hợp polymer: tổng hợp ethylic alcohol; tổng hợp acetic acid; sản xuất dung môi; kích thích quả mau chín; sản xuất polyethylene (PE), poly(vinyl chloride) (PVC).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = '4. Ứng dụng của ethylene (Hình 24.2)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'knowledge', 'example', 'Câu hỏi SGK', 'Propylene là một alkene, có công thức cấu tạo CH₃–CH=CH₂. Propylene có tính chất hoá học tương tự ethylene vì có liên kết đôi C=C trong phân tử.
• Cháy: 2C₃H₆ + 9O₂ →(t°) 6CO₂ + 6H₂O
• Cộng bromine: CH₃–CH=CH₂ + Br₂ → CH₃–CHBr–CH₂Br
• Trùng hợp: nCH₃–CH=CH₂ →(t°, p, xúc tác) (–CH₂–CH(CH₃)–)ₙ (polypropylene, PP).', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'knowledge' and x.title = 'Câu hỏi SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24), 'experiment', 'text', 'Thí nghiệm: Điều chế và thử tính chất của ethylene (Hình 24.1)', 'Chuẩn bị: bình cầu có nhánh 250 mL đựng dung dịch cồn 96° và dung dịch H₂SO₄ đặc đã được trộn đều, đá bọt; ống nghiệm chứa khoảng 2 mL nước bromine; bình thuỷ tinh chứa dung dịch NaOH; ống dẫn thuỷ tinh đầu vuốt nhọn; ống dẫn thuỷ tinh hình chữ L.
Tiến hành: đun nóng bình cầu đến khi khí ethylene sinh ra và đi vào ống dẫn thuỷ tinh có đầu vuốt nhọn. Dùng que đóm đang cháy để đốt ethylene ở đầu vuốt nhọn của ống dẫn. Thay ống dẫn thuỷ tinh đầu vuốt nhọn bằng ống dẫn thuỷ tinh hình chữ L và dẫn khí ethylene vào ống nghiệm đựng nước bromine.
Kết quả: ở đầu ống dẫn vuốt nhọn, ethylene cháy được, toả nhiệt; ở ống nghiệm đựng nước bromine, nước bromine mất màu (màu vàng cam nhạt dần rồi mất màu). Nhận xét: ethylene có phản ứng cháy và phản ứng với nước bromine.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 24) and x.section = 'experiment' and x.title = 'Thí nghiệm: Điều chế và thử tính chất của ethylene (Hình 24.1)');

-- Bài 25
update public.lessons set summary = 'Dầu mỏ, khí mỏ dầu và khí thiên nhiên là nhiên liệu hoá thạch có thành phần chính là hydrocarbon; nhiên liệu là chất cháy được, toả nhiệt và phát sáng, cần sử dụng an toàn, tiết kiệm.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'objective', 'Nêu được khái niệm, thành phần, trạng thái tự nhiên của dầu mỏ, khí thiên nhiên và khí mỏ dầu.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Nêu được khái niệm, thành phần, trạng thái tự nhiên của dầu mỏ, khí thiên nhiên và khí mỏ dầu.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'objective', 'Trình bày được phương pháp khai thác dầu mỏ, khí thiên nhiên và khí mỏ dầu; một số sản phẩm chế biến từ dầu mỏ; ứng dụng của dầu mỏ và khí thiên nhiên (là nguồn nhiên liệu và nguyên liệu quý trong công nghiệp).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Trình bày được phương pháp khai thác dầu mỏ, khí thiên nhiên và khí mỏ dầu; một số sản phẩm chế biến từ dầu mỏ; ứng dụng của dầu mỏ và khí thiên nhiên (là nguồn nhiên liệu và nguyên liệu quý trong công nghiệp).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'objective', 'Nêu được khái niệm về nhiên liệu, các dạng nhiên liệu phổ biến (rắn, lỏng, khí).', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Nêu được khái niệm về nhiên liệu, các dạng nhiên liệu phổ biến (rắn, lỏng, khí).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'objective', 'Trình bày được cách sử dụng nhiên liệu (gas, dầu hoả, than,...), từ đó có cách ứng xử thích hợp đối với việc sử dụng nhiên liệu trong cuộc sống.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Trình bày được cách sử dụng nhiên liệu (gas, dầu hoả, than,...), từ đó có cách ứng xử thích hợp đối với việc sử dụng nhiên liệu trong cuộc sống.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'requirement', 'Sử dụng các loại nhiên liệu một cách tiết kiệm, hiệu quả, an toàn.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.content = 'Sử dụng các loại nhiên liệu một cách tiết kiệm, hiệu quả, an toàn.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', '1. Dầu mỏ, khí mỏ dầu và khí thiên nhiên: khái niệm, thành phần, trạng thái tự nhiên', 'Dầu mỏ là nhiên liệu hoá thạch, có trong vỏ Trái Đất. Thành phần chính của dầu mỏ là các hydrocarbon. Thành phần dầu mỏ có thể khác nhau tuỳ thuộc vào vị trí mỏ dầu.
Trong tự nhiên, dầu mỏ thường tập trung thành những khu vực ở trong lòng đất, gọi là các mỏ dầu. Mỏ dầu thường có ba lớp (Hình 25.1):
• Lớp trên cùng là khí mỏ dầu (hay còn gọi là khí đồng hành). Khí mỏ dầu chứa chủ yếu là khí methane (khoảng 75%) và một số hydrocarbon khí khác.
• Lớp dầu lỏng có hoà tan khí và hỗn hợp phức tạp của nhiều loại hydrocarbon và một lượng nhỏ các hợp chất khác.
• Dưới đáy mỏ dầu là một lớp nước mặn.
Khí thiên nhiên cũng là nhiên liệu hoá thạch ở dưới lòng đất. Trong tự nhiên, khí thiên nhiên tập trung trong các mỏ khí dưới lòng đất hay rải rác thoát ra từ lớp bùn ở đáy ao. Thành phần chính của khí thiên nhiên là methane (khoảng 95%) và một số hydrocarbon khác như ethane, propane và butane. Trong khí thiên nhiên cũng có một lượng nhỏ carbon dioxide và nitrogen,...', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = '1. Dầu mỏ, khí mỏ dầu và khí thiên nhiên: khái niệm, thành phần, trạng thái tự nhiên');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', '2. Phương pháp khai thác và chế biến', 'a) Dầu mỏ và khí mỏ dầu: khai thác dầu mỏ và khí mỏ dầu gồm nhiều giai đoạn: khoan, thu dầu và khí; loại bỏ tạp chất để thu dầu thô, vận chuyển đến nhà máy lọc dầu (bằng ống dẫn hoặc tàu chở dầu); tại nhà máy lọc dầu, dầu thô được xử lí chủ yếu bằng phương pháp chưng cất để thu được nhiều loại sản phẩm khác nhau ở các khoảng nhiệt độ khác nhau. Sau đó, dầu và khí sẽ được vận chuyển đến cơ sở sử dụng với các mục đích khác nhau (Bảng 25.1).
Ứng dụng của các sản phẩm chưng cất dầu mỏ (Bảng 25.1): khí hoá lỏng – nhiên liệu (sưởi ấm, bếp gas); dầu nhẹ – dung môi; naphtha nhẹ – dung môi; xăng – nhiên liệu cho động cơ đốt trong (xe máy, ô tô,...); dầu hoả – nhiên liệu cho động cơ phản lực; dầu diesel – nhiên liệu cho động cơ diesel và các lò nung; dầu bôi trơn – chất bôi trơn; sáp paraffin – sáp bóng, sáp dầu khoáng; nhựa đường – bề mặt đường, giấy dầu lợp mái.
b) Khí thiên nhiên: được khai thác bằng cách khoan xuống mỏ khí và khí sẽ tự phun lên do áp suất ở các mỏ khí lớn hơn áp suất khí quyển. Sau đó, khí được vận chuyển đến nhà máy để xử lí nhằm đạt được chất lượng mong muốn trước khi phân phối đến các điểm tiêu thụ khác nhau.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = '2. Phương pháp khai thác và chế biến');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', '3. Nhiên liệu: khái niệm và phân loại', 'Nhiên liệu là những chất cháy được, khi cháy toả nhiệt và phát sáng. Nhiên liệu được phân loại dựa trên một số cơ sở khác nhau.
Dựa trên trạng thái tồn tại, nhiên liệu được phân loại thành nhiên liệu rắn (như gỗ, than mỏ), nhiên liệu lỏng (như xăng, dầu diesel, ethanol) và nhiên liệu khí (như hydrogen, methane, propane hay butane).', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = '3. Nhiên liệu: khái niệm và phân loại');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', '4. Sử dụng nhiên liệu', 'Trong cuộc sống hằng ngày, các nhiên liệu như xăng, dầu hoả, gas hay than đáp ứng nhiều nhu cầu sử dụng của con người. Xe máy, ô tô và máy bay dùng nhiên liệu xăng và dầu hoả. Ở nhiều nơi trên thế giới, gas là nguồn nhiên liệu chính để sưởi ấm, nấu ăn, vận hành các thiết bị máy. Than là nhiên liệu quan trọng cho các nhà máy nhiệt điện, công nghiệp luyện kim.
Lựa chọn nhiên liệu phù hợp và sử dụng nhiên liệu một cách tiết kiệm, hiệu quả không chỉ mang lại nhiều lợi ích kinh tế mà còn góp phần bảo vệ môi trường. Vì vậy, cần tắt thiết bị khi không sử dụng, ưu tiên tham gia giao thông bằng phương tiện công cộng, bảo dưỡng xe thường xuyên để đảm bảo động cơ xe hoạt động hiệu quả và tiết kiệm nhiên liệu,...
Nhiên liệu là các chất dễ cháy, vì vậy việc sử dụng và lưu trữ nhiên liệu cần tuân thủ nghiêm ngặt các nguyên tắc về an toàn cháy nổ và hướng dẫn của nhà sản xuất. Xăng phải được bảo quản trong bình chứa đúng tiêu chuẩn. Bình gas cần được đặt nơi thông thoáng và cách xa nguồn nhiệt, đồng thời chúng ta nên thường xuyên kiểm tra để tránh rò rỉ. Không đốt cháy than, gas,... trong không gian kín, tránh nguy cơ ngộ độc khí.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = '4. Sử dụng nhiên liệu');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'knowledge', 'text', 'Em đã học', 'Dầu mỏ, khí mỏ dầu và khí thiên nhiên là nhiên liệu hoá thạch dưới bề mặt Trái Đất. Dầu mỏ gồm hỗn hợp của các hydrocarbon và hợp chất khác. Khí thiên nhiên có thành phần chính là methane (khoảng 95%) và ethane, propane, butane,... Phương pháp khai thác và chế biến: khoan, thu khí và dầu từ mỏ dầu, chưng cất dầu mỏ để thu được các sản phẩm khác nhau; khoan xuống mỏ khí thiên nhiên và thu khí. Nhiên liệu là những chất cháy được, khi cháy toả nhiệt và phát sáng. Nhiên liệu là các chất dễ cháy nên khi sử dụng cần tuân thủ nghiêm ngặt các biện pháp phòng cháy và chữa cháy. Trữ lượng nhiên liệu hoá thạch có hạn và việc sử dụng loại nhiên liệu này gây ô nhiễm môi trường, nên cần sử dụng tiết kiệm và hiệu quả.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'knowledge' and x.title = 'Em đã học');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25), 'experiment', 'text', 'Hoạt động SGK 25: Mỏ dầu, nhiên liệu (bài này không có thí nghiệm thực hành)', 'SGK Bài 25 gồm các hoạt động quan sát hình, tìm hiểu thông tin và thảo luận, không có thí nghiệm thực hành.
• Hình 25.1 – sơ đồ cấu tạo mỏ dầu: lớp khí, lớp dầu, lớp nước mặn.
• Bảng 25.1 – ứng dụng các sản phẩm chưng cất dầu mỏ.
• Hình 25.2 – một số loại nhiên liệu phổ biến (gỗ, than đá, xăng, dầu diesel, xăng sinh học, khí thiên nhiên); trạng thái tồn tại của mỗi nhiên liệu ở điều kiện thường.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 25) and x.section = 'experiment' and x.title = 'Hoạt động SGK 25: Mỏ dầu, nhiên liệu (bài này không có thí nghiệm thực hành)');

-- Bài 26
update public.lessons set summary = 'Ethylic alcohol (C₂H₅OH) là chất lỏng, tan vô hạn trong nước; nhóm –OH quyết định tính chất: cháy toả nhiệt, tác dụng với natri; được điều chế bằng lên men tinh bột hoặc cộng nước vào ethylene.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 26) and summary is null;
