insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32), 'objective', 'Nêu được khái niệm chất dẻo, tơ, cao su, vật liệu composite và cách sử dụng, bảo quản một số vật dụng làm bằng chất dẻo, tơ, cao su trong gia đình an toàn, hiệu quả.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32) and x.content = 'Nêu được khái niệm chất dẻo, tơ, cao su, vật liệu composite và cách sử dụng, bảo quản một số vật dụng làm bằng chất dẻo, tơ, cao su trong gia đình an toàn, hiệu quả.');
