insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32), 'requirement', 'Biết cách phân loại để tái chế một số rác thải nhựa.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32) and x.content = 'Biết cách phân loại để tái chế một số rác thải nhựa.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32), 'requirement', 'Biết được các tác hại của rác thải nhựa, từ đó có biện pháp để giảm thiểu rác thải nhựa.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32) and x.content = 'Biết được các tác hại của rác thải nhựa, từ đó có biện pháp để giảm thiểu rác thải nhựa.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32), 'knowledge', 'text', '1. Khái niệm, đặc điểm cấu tạo và phân loại', 'Khái niệm: polymer là những chất có khối lượng phân tử rất lớn do nhiều đơn vị nhỏ (gọi là mắt xích) liên kết với nhau tạo nên. Các phân tử nhỏ kết hợp với nhau tạo nên polymer được gọi là monomer.
Tinh bột có công thức chung (C₆H₁₀O₅)ₙ, được tạo thành do hàng nghìn đơn vị glucose kết hợp với nhau; các đơn vị glucose (C₆H₁₀O₅) này được gọi là mắt xích.
Một số ví dụ (Bảng 32.1): polyethylene (PE) (–CH₂–CH₂–)ₙ, monomer là ethylene CH₂=CH₂, mắt xích –CH₂–CH₂–; polypropylene (PP) (–CH₂–CH(CH₃)–)ₙ, monomer là propylene CH₂=CH–CH₃, mắt xích –CH₂–CH(CH₃)–.
Đặc điểm cấu tạo: các mắt xích của polymer có thể nối với nhau thành mạch không phân nhánh như amylose (Hình 32.1a); mạch phân nhánh như amylopectin, glycogen (Hình 32.1b); mạng không gian như nhựa bakelite, cao su lưu hoá (Hình 32.1c).
Phân loại theo nguồn gốc: polymer thiên nhiên (có sẵn trong tự nhiên như tinh bột, cellulose, protein (sợi tơ tằm, lông cừu), cao su thiên nhiên,...) và polymer tổng hợp (được tổng hợp bằng phương pháp hoá học, ví dụ PE, PP,...).
Điều chế: nCH₂=CH₂ →(t°, p, xúc tác) (–CH₂–CH₂–)ₙ (PE);  nCH₂=CH–CH₃ →(t°, p, xúc tác) (–CH₂–CH(CH₃)–)ₙ (PP).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32) and x.section = 'knowledge' and x.title = '1. Khái niệm, đặc điểm cấu tạo và phân loại');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32), 'knowledge', 'text', '2. Tính chất vật lí của polymer', 'Hầu hết polymer là những chất rắn, không bay hơi, không có nhiệt độ nóng chảy xác định (một số polymer không nóng chảy) và không tan trong nước. Một số polymer tan được trong dung môi hữu cơ.
Các polymer bị nóng chảy ở nhiệt độ cao được gọi là các polymer nhiệt dẻo. Tính chất này được ứng dụng trong sản xuất bằng cách cho nóng chảy polymer, sau đó đổ vào khuôn tạo hình rồi làm nguội sẽ thu được các vật dụng có hình thù mong muốn.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32) and x.section = 'knowledge' and x.title = '2. Tính chất vật lí của polymer');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32), 'knowledge', 'text', '3. Một số vật liệu polymer phổ biến', 'a) Chất dẻo: chất dẻo là loại vật liệu được chế tạo từ các polymer có tính dẻo. Tính dẻo của vật liệu là tính bị biến dạng khi chịu tác dụng của nhiệt, áp lực bên ngoài và vẫn giữ được sự biến dạng đó khi thôi tác dụng. Thành phần của chất dẻo gồm polymer, chất độn, chất hoá dẻo, chất tạo màu,... Chất dẻo dễ bị mềm dẻo ở môi trường nhiệt độ cao, một số bị phân huỷ tạo thành các sản phẩm độc hại. Vì vậy, không để các vật dụng làm từ chất dẻo ở gần nguồn nhiệt cao (bếp gas, lò nướng,...). Trên các vỏ chai, hộp, đồ dùng bằng nhựa thường có các kí hiệu an toàn và kí hiệu phân loại nhựa; cần tìm hiểu thông tin để lựa chọn đồ nhựa phù hợp với mục đích sử dụng (Hình 32.3).
b) Tơ: tơ là những vật liệu polymer có cấu tạo không phân nhánh và có thể kéo dài thành sợi. Dựa vào nguồn gốc, tơ thường được chia thành: tơ thiên nhiên (như tơ tằm, bông vải, len lông cừu,...); tơ tổng hợp (như tơ nylon, tơ polyester,...). Mỗi loại tơ có các tính chất đặc trưng khác nhau nên khi sử dụng các vật dụng làm từ tơ (quần áo, chăn, ga,...) được bền, đẹp, cần đọc kĩ hướng dẫn sử dụng trước khi giặt là để lựa chọn chế độ giặt (nếu giặt bằng máy), nhiệt độ là, sấy và chất giặt rửa phù hợp.
c) Cao su: cao su là vật liệu polymer có tính đàn hồi (tính bị biến dạng khi bị tác dụng của lực bên ngoài và trở lại trạng thái ban đầu khi lực đó thôi tác dụng). Cao su được phân thành hai loại: cao su thiên nhiên (được lấy từ mủ cây cao su) và cao su tổng hợp (được tổng hợp từ một số monomer). Cao su có tính đàn hồi, không thấm nước, không thấm khí, chịu mài mòn, cách điện,... nên được sử dụng rộng rãi trong nhiều lĩnh vực như sản xuất các loại lốp xe, băng tải cao su, ống dẫn, gioăng đệm, áo lặn,... Khi sử dụng, chú ý không để ở nơi có nhiệt độ quá cao, nơi có nhiệt độ quá thấp hoặc nơi có ánh sáng mạnh; hạn chế để xăng, dầu, mỡ, hoá chất dính vào cao su.
d) Vật liệu composite: vật liệu composite là vật liệu được tổ hợp từ hai hay nhiều vật liệu khác nhau, gồm vật liệu cốt và vật liệu nền. Vật liệu cốt có vai trò tăng cường tính chất cơ học của vật liệu, thường ở dạng sợi (sợi thuỷ tinh, sợi carbon,...) và dạng hạt. Vật liệu nền thường là các vật liệu có độ dẻo lớn (như một số polymer) đóng vai trò liên kết các vật liệu cốt với nhau. Vật liệu composite được sử dụng rộng rãi như làm ống dẫn nước, bồn chứa nước và hoá chất, vật liệu xây dựng, thân vỏ ô tô, máy bay, tàu thuyền,...', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32) and x.section = 'knowledge' and x.title = '3. Một số vật liệu polymer phổ biến');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32), 'knowledge', 'text', '4. Ứng dụng của polyethylene và vấn đề ô nhiễm môi trường', 'Polyethylene (PE) là một polymer được sử dụng rất phổ biến để tạo ra nhiều sản phẩm gia dụng như tải đựng, màng bọc, chai, ống nhựa, vỏ dây điện, đồ chơi trẻ em,... (Hình 32.6).
Hiện nay ô nhiễm môi trường gây ra do sử dụng polyethylene và các polymer không phân huỷ sinh học đang ở mức đáng báo động, ảnh hưởng đến môi trường sinh thái, sự sinh trưởng, phát triển của động, thực vật và sức khoẻ con người. Việc lạm dụng các sản phẩm nhựa được làm từ polyethylene (túi, chai, lọ, bình nhựa, cốc, thìa nhựa dùng một lần,...) đã và đang để lại những hậu quả nghiêm trọng đối với môi trường.
Để hạn chế tình trạng gây ô nhiễm môi trường khi sử dụng vật liệu polymer, theo khuyến cáo của Bộ Tài nguyên và Môi trường, cần áp dụng nguyên tắc 5R để giảm thiểu rác thải nhựa (Hình 32.7): Đổi mới công nghệ (Renew – sử dụng vật liệu polymer được sản xuất từ nguyên liệu tái tạo hoặc có thể phân huỷ sinh học); Từ chối (Refuse – từ chối các sản phẩm làm từ nhựa không phân huỷ sinh học, lựa chọn các sản phẩm làm từ vật liệu thân thiện môi trường); Giảm thiểu (Reduce – giảm thiểu sử dụng các đồ vật bằng nhựa sử dụng một lần, thay thế bằng vật dụng có thể sử dụng nhiều lần); Tái sử dụng (Reuse – tái sử dụng các đồ dùng bằng vật liệu polymer thành các sản phẩm hữu dụng phục vụ đời sống); Tái chế (Recycle – thu gom, phân loại các loại nhựa có thể tái chế, tránh vứt bỏ ra môi trường).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32) and x.section = 'knowledge' and x.title = '4. Ứng dụng của polyethylene và vấn đề ô nhiễm môi trường');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32), 'experiment', 'text', 'Hoạt động SGK 32: Phân loại và sử dụng polymer (bài này không có thí nghiệm thực hành)', 'SGK Bài 32 gồm các hoạt động quan sát hình, tìm hiểu thông tin, không có thí nghiệm thực hành.
• Bảng 32.1: PE và PP – công thức polymer, monomer, mắt xích.
• Hình 32.3: ý nghĩa các kí hiệu in trên đồ nhựa gia dụng (an toàn khi dùng thực phẩm, dùng được trong lò vi sóng, sử dụng trong máy rửa chén, an toàn khi đông lạnh, nhiệt độ tối đa sử dụng, mã số nhận diện nhựa).
• Hình 32.7: nguyên tắc 5R giúp hạn chế ô nhiễm môi trường khi sử dụng vật liệu polymer.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 32) and x.section = 'experiment' and x.title = 'Hoạt động SGK 32: Phân loại và sử dụng polymer (bài này không có thí nghiệm thực hành)');

-- Bài 33
update public.lessons set summary = 'Vỏ Trái Đất chứa nhiều nhất oxygen, silicon, nhôm, sắt, calcium, natri, kali, magnesium; các dạng chất chủ yếu là oxide và muối; khai thác tài nguyên cần tiết kiệm, bảo vệ và sử dụng vật liệu tái chế.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 33) and summary is null;
